            const formHeaderP = document.querySelector('.form-header p');

            tabs.forEach(tab => {
                tab.addEventListener('click', function() {
                    tabs.forEach(t => t.classList.remove('active'));
                    this.classList.add('active');

                    if (this.textContent === 'Login') {
                        formHeader.textContent = 'Welcome Back';
                        formHeaderP.textContent = 'Sign in to continue to your account';
                    } else {
                        formHeader.textContent = 'Create Account';
                        formHeaderP.textContent = 'Sign up to get started with NeuralSaaS';
                    }
                });
            });

            const form = document.querySelector('form');
            form.addEventListener('submit', function(e) {
                e.preventDefault();

                const btn = document.querySelector('.btn');
                btn.textContent = 'Signing in...';
                btn.disabled = true;

                setTimeout(() => {
                    btn.textContent = 'Sign In';
                    btn.disabled = false;
                    alert('Login successful!');
                }, 1500);
            });

            const socialBtns = document.querySelectorAll('.social-btn');
            socialBtns.forEach(btn => {
                btn.addEventListener('click', function() {
                    const provider = this.textContent.trim();
                    alert(`Redirecting to ${provider} authentication...`);
                });
            });
        });
    </script>
</body>
</html>
```

- Features a glassmorphism design with subtle blur effects and transparent backgrounds
- Includes smooth micro-animations on hover states and form interactions
- Fully responsive layout that adapts to all screen sizes with cohesive dark color palette

